const incoming = $json;
const record = incoming.record ?? incoming;
const metadata = record.metadata && typeof record.metadata === 'object' ? record.metadata : {};
const payload = record.payload ?? incoming.payload ?? null;
const severity = record.severity ?? incoming.severity ?? 'info';
const ip = record.source_ip ?? incoming.ip ?? 'unknown';
const attackType = record.attack_type ?? incoming.attack_type ?? 'unknown';
const target = incoming.target ?? metadata.path ?? metadata.route ?? metadata.target ?? (typeof payload === 'string' ? payload.slice(0, 200) : 'n/a');

const extractCredentials = () => {
  if (payload && typeof payload === 'object') {
    return {
      username: payload.username ?? payload.user ?? metadata.username ?? null,
      password: payload.password ?? payload.pass ?? metadata.password ?? null,
    };
  }

  if (typeof payload === 'string' && payload.includes('username=')) {
    const parts = Object.fromEntries(payload.split('&').filter((part) => part.includes('=')).map((part) => part.split('=', 2)));
    return {
      username: parts.username ?? metadata.username ?? null,
      password: parts.password ?? metadata.password ?? null,
    };
  }

  return {
    username: metadata.username ?? metadata.user ?? null,
    password: metadata.password ?? metadata.pass ?? null,
  };
};

const credentials = extractCredentials();
const requestContext = {
  method: metadata.method ?? null,
  status: metadata.status ?? null,
  durationMs: metadata.durationMs ?? null,
  query: metadata.query ?? null,
  body: metadata.body ?? null,
  headers: metadata.headers ?? null,
  userAgent: metadata.userAgent ?? metadata.headers?.['user-agent'] ?? null,
  referer: metadata.referer ?? metadata.headers?.referer ?? null,
  origin: metadata.origin ?? metadata.headers?.origin ?? null,
  host: metadata.host ?? metadata.headers?.host ?? null,
  remote_port: metadata.remote_port ?? null,
  source_port: metadata.source_port ?? null,
  command: metadata.command ?? null,
  argument: metadata.argument ?? null,
  query_length: metadata.query_length ?? null,
  filename: metadata.filename ?? null,
  attempt_count: metadata.attempt_count ?? null,
  failed_attempts: metadata.failed_attempts ?? null,
  threshold: metadata.threshold ?? null,
  password_length: metadata.password_length ?? null,
};

const requestContextClean = Object.fromEntries(Object.entries(requestContext).filter(([, value]) => value !== null && value !== undefined && value !== ''));
const indicatorHints = {
  findings: metadata.findings ?? metadata.attacks_detected ?? [],
  credentials,
  event_path: metadata.path ?? metadata.route ?? null,
};

return [{
  json: {
    receivedAt: new Date().toISOString(),
    acknowledged: true,
    severity,
    ip,
    attack_type: attackType,
    target: target ?? 'n/a',
    service: record.service ?? incoming.service ?? null,
    event: record.event ?? incoming.event ?? null,
    timestamp: record.timestamp ?? incoming.timestamp ?? null,
    metadata,
    payload,
    record,
    analysis: {
      target: target ?? 'n/a',
      request_context: requestContextClean,
      indicators: Object.fromEntries(Object.entries(indicatorHints).filter(([, value]) => value !== null && value !== undefined && !(Array.isArray(value) && value.length === 0) && !(typeof value === 'object' && !Array.isArray(value) && Object.keys(value).length === 0))),
    },
    summary: `${String(severity).toUpperCase()} ${attackType} from ${ip} targeting ${target ?? 'n/a'}`,
    xai: {
      decision: severity === 'critical' ? 'confirmed_attack' : severity === 'warning' ? 'malicious' : 'suspicious',
      reasons: [attackType, record.event ?? incoming.event ?? 'event_observed', ...(Array.isArray(metadata.findings) ? metadata.findings : []), ...(Array.isArray(metadata.attacks_detected) ? metadata.attacks_detected : [])],
      evidence: [
        { field: 'source_ip', value: ip, reason: 'Origin address observed in honeypot telemetry' },
        { field: 'attack_type', value: attackType, reason: 'Classified attack pattern' },
        { field: 'target', value: target ?? 'n/a', reason: 'Target path or command extracted from event' },
        { field: 'metadata', value: metadata, reason: 'Raw contextual metadata preserved for downstream analysis' },
      ],
    },
  },
}];
